import itertools

# We'll search for all-interval series of size 10 with given constraints.
# x[0]=0, x[3]=8, d[1]=8 (|x[2]-x[1]|=8)

n = 10
all_nums = set(range(n))

# We'll use backtracking with pruning.

solutions = []

def backtrack(x, used, diffs_used):
    i = len(x)
    if i == n:
        # check all diffs 1..9 used
        if diffs_used == set(range(1, n)):
            solutions.append(x[:])
        return
    # Determine candidates for x[i]
    candidates = all_nums - used
    # Apply constraints
    if i == 0:
        candidates = {0}
    elif i == 3:
        candidates = {8}
    # Also if i == 2, we have constraint on d[1] = |x[2]-x[1]| = 8
    # We'll handle after placing.
    for val in candidates:
        # If not first, compute diff
        if i > 0:
            d = abs(val - x[-1])
            if d in diffs_used:
                continue
            if d < 1 or d > 9:
                continue
            # Additional constraint: d[1] = 8
            if i == 2:  # this is d[1] (since d[0] is between x0,x1; d[1] between x1,x2)
                if d != 8:
                    continue
            # Also, we need to ensure that eventually we can get all diffs 1..9.
            # Simple pruning: if remaining unused numbers cannot produce needed diffs? skip for now.
            new_used = used | {val}
            new_diffs = diffs_used | {d}
            backtrack(x + [val], new_used, new_diffs)
        else:
            backtrack(x + [val], used | {val}, diffs_used)

backtrack([], set(), set())
print("Number of solutions:", len(solutions))
if solutions:
    print("First solution:", solutions[0])
    # verify
    x = solutions[0]
    print("x:", x)
    diffs = [abs(x[i+1]-x[i]) for i in range(n-1)]
    print("diffs:", sorted(diffs))
